export default function EnrollVehicle() {
  return (
    <div className="flex min-h-screen items-center justify-center bg-zinc-50 dark:bg-black">
      <main className="flex flex-col items-center justify-center gap-8 py-32 px-16">
        <h1 className="text-4xl font-semibold text-black dark:text-zinc-50">
          Enroll Vehicle
        </h1>
        <p className="text-lg text-zinc-600 dark:text-zinc-400">
          Vehicle enrollment form coming soon...
        </p>
      </main>
    </div>
  );
}

"use client";

import { useState } from "react";

export default function EnrollVehiclePage() {
  const [form, setForm] = useState({
    firstName: "",
    lastName: "",
    designation: "",
    department: "",
    branch: "",
    email: "",
    issuanceCategory: "",
    plateNumber: "",
    vin: "",
    engineNumber: "",
    yearModel: "",
    vehicleModel: "",
    tplPolicyNumber: "",
    moaDate: "",
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    console.log("Form Data:", form);
    alert("Vehicle Enrolled!");
  };

  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <h1 className="text-2xl font-bold mb-6">Enroll Vehicle</h1>

      <form
        onSubmit={handleSubmit}
        className="bg-teal-900 text-white p-6 rounded-xl shadow-lg max-w-5xl"
      >
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Employee Information */}
          <div>
            <h2 className="font-semibold mb-3">Employee Information</h2>

            <div className="grid grid-cols-2 gap-3">
              <input
                name="firstName"
                placeholder="First Name"
                onChange={handleChange}
                className="input"
              />
              <input
                name="lastName"
                placeholder="Last Name"
                onChange={handleChange}
                className="input"
              />
            </div>

            <input
              name="designation"
              placeholder="Designation"
              onChange={handleChange}
              className="input mt-3"
            />

            <input
              name="department"
              placeholder="Department"
              onChange={handleChange}
              className="input mt-3"
            />

            <input
              name="branch"
              placeholder="Branch"
              onChange={handleChange}
              className="input mt-3"
            />

            <input
              name="email"
              placeholder="Company Email"
              onChange={handleChange}
              className="input mt-3"
            />
          </div>

          {/* Vehicle Information */}
          <div>
            <h2 className="font-semibold mb-3">Motorcycle / Vehicle Information</h2>

            <input
              name="issuanceCategory"
              placeholder="Issuance Category"
              onChange={handleChange}
              className="input"
            />

            <div className="grid grid-cols-2 gap-3 mt-3">
              <input
                name="plateNumber"
                placeholder="Plate No."
                onChange={handleChange}
                className="input"
              />
              <input
                name="vin"
                placeholder="Chassis No / VIN"
                onChange={handleChange}
                className="input"
              />
            </div>

            <input
              name="engineNumber"
              placeholder="Engine No."
              onChange={handleChange}
              className="input mt-3"
            />

            <div className="grid grid-cols-2 gap-3 mt-3">
              <input
                name="yearModel"
                placeholder="Year Model"
                onChange={handleChange}
                className="input"
              />
              <input
                name="vehicleModel"
                placeholder="Vehicle Model"
                onChange={handleChange}
                className="input"
              />
            </div>

            <input
              name="tplPolicyNumber"
              placeholder="TPL Policy No."
              onChange={handleChange}
              className="input mt-3"
            />

            <input
              type="date"
              name="moaDate"
              onChange={handleChange}
              className="input mt-3"
            />
          </div>
        </div>

        {/* Buttons */}
        <div className="flex justify-end gap-3 mt-6">
          <button
            type="reset"
            className="px-4 py-2 bg-gray-300 text-black rounded-md hover:bg-gray-400"
          >
            Clear Entries
          </button>

          <button
            type="submit"
            className="px-6 py-2 bg-green-500 hover:bg-green-600 text-white rounded-md font-semibold"
          >
            Enroll
          </button>
        </div>
      </form>
    </div>
  );
}
